import { ProjEntity, ProjStatus } from './proj.entity';

/**
 * Unit spec for the PROJ aggregate root.
 *
 * Covers the invariants the entity enforces itself — no Nest, no Prisma, no
 * HTTP. Generated by node-module-generator; extend it as the real aggregate
 * replaces the skeleton.
 */
describe('ProjEntity', () => {
  const validProps = () => ({
    id: '11111111-1111-4111-8111-111111111111',
    name: 'Valid name',
    description: 'optional',
    status: ProjStatus.ACTIVE,
    empresaId: '22222222-2222-4222-8222-222222222222',
    createdAt: new Date('2020-01-01T00:00:00Z'),
    updatedAt: new Date('2020-01-01T00:00:00Z'),
  });

  it('builds from valid props', () => {
    const entity = new ProjEntity(validProps());

    expect(entity.id).toBe(validProps().id);
    expect(entity.isActive()).toBe(true);
    expect(entity.empresaId).toBe(validProps().empresaId);
  });

  it('rejects a missing id', () => {
    expect(() => new ProjEntity({ ...validProps(), id: '' })).toThrow(
      /id is required/,
    );
  });

  it('rejects a name shorter than two characters', () => {
    expect(() => new ProjEntity({ ...validProps(), name: 'a' })).toThrow(
      /at least 2 characters/,
    );
  });

  it('rejects a name that is only whitespace', () => {
    expect(() => new ProjEntity({ ...validProps(), name: '   ' })).toThrow(
      /at least 2 characters/,
    );
  });

  it('rejects a missing empresaId — every query is scoped by it', () => {
    expect(
      () => new ProjEntity({ ...validProps(), empresaId: '' }),
    ).toThrow();
  });

  it('with() returns a new instance and refreshes updatedAt', () => {
    const original = new ProjEntity(validProps());
    const renamed = original.with({ name: 'Renamed' });

    expect(renamed).not.toBe(original);
    expect(renamed.name).toBe('Renamed');
    expect(original.name).toBe(validProps().name);
    expect(renamed.updatedAt.getTime()).toBeGreaterThan(
      original.updatedAt.getTime(),
    );
  });

  it('with() keeps identity and creation time', () => {
    const original = new ProjEntity(validProps());
    const changed = original.with({ name: 'Other name' });

    expect(changed.id).toBe(original.id);
    expect(changed.createdAt).toEqual(original.createdAt);
    expect(changed.empresaId).toBe(original.empresaId);
  });

  it('archive() moves the aggregate out of the active state', () => {
    const archived = new ProjEntity(validProps()).archive();

    expect(archived.status).toBe(ProjStatus.ARCHIVED);
    expect(archived.isActive()).toBe(false);
  });
});
